package com.yeyamo_mobile.api.mission_reward_service.infrastructure.persistence;
import java.time.Instant;import java.util.*;import com.yeyamo_mobile.api.mission_reward_service.domain.AdminDefinitionStatus;import jakarta.persistence.*;
@Entity@Table(name="badge_definitions")public class BadgeDefinitionEntity{
 @Id private UUID id;@Column(nullable=false,unique=true,length=80)private String code;@Column(nullable=false,length=180)private String name;@Column(nullable=false,length=1000)private String description;@Column(name="condition_json",nullable=false,columnDefinition="TEXT")private String condition;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private AdminDefinitionStatus status;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;
 public static BadgeDefinitionEntity create(String code,String name,String description,String condition){BadgeDefinitionEntity e=new BadgeDefinitionEntity();e.id=UUID.randomUUID();e.code=required(code);e.name=required(name);e.description=required(description);e.condition=required(condition);e.status=AdminDefinitionStatus.DRAFT;e.createdAt=Instant.now();e.updatedAt=e.createdAt;return e;}public void update(String name,String description,String condition){this.name=required(name);this.description=required(description);this.condition=required(condition);updatedAt=Instant.now();}public void status(AdminDefinitionStatus status){this.status=Objects.requireNonNull(status);updatedAt=Instant.now();}private static String required(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("Required value");return v.trim();}
 public UUID getId(){return id;}public String getCode(){return code;}public String getName(){return name;}public String getDescription(){return description;}public String getCondition(){return condition;}public AdminDefinitionStatus getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}
}
